import{_ as t,c as h,o as i,a2 as a}from"./chunks/framework.B7el9cAC.js";const s=JSON.parse('{"title":"Mục 3.1 – AI là gì?","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-3/3.1-ai-la-gi.md","filePath":"chuong-3/3.1-ai-la-gi.md","lastUpdated":1774578382000}'),o={name:"chuong-3/3.1-ai-la-gi.md"};function g(c,n,r,u,l,d){return i(),h("div",null,[...n[0]||(n[0]=[a('<h1 id="muc-3-1-–-ai-la-gi" tabindex="-1">Mục 3.1 – AI là gì? <a class="header-anchor" href="#muc-3-1-–-ai-la-gi" aria-label="Permalink to &quot;Mục 3.1 – AI là gì?&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p>Bạn đã bao giờ tự hỏi: <strong>Tại sao TikTok cứ hiểu ý bạn?</strong> Bạn xem một video về mèo, rồi đột nhiên cả màn hình toàn mèo. Bạn nói chuyện với Siri hay Google Assistant và nó trả lời đúng câu hỏi. Camera điện thoại tự nhận ra khuôn mặt bạn để mở khóa. Tất cả những điều đó đều do <strong>AI</strong> làm được.</p><p><strong>Tại sao cần AI?</strong> Con người rất giỏi suy nghĩ, cảm nhận, và sáng tạo — nhưng lại chậm khi xử lý hàng triệu dữ liệu cùng lúc. Máy tính xử lý nhanh nhưng không &quot;nghĩ&quot; được. AI ra đời để kết hợp tốc độ của máy tính với khả năng &quot;nhận biết và quyết định&quot; gần giống con người.</p><p><strong>Ví dụ đời thực:</strong></p><ul><li>🏠 <strong>Tại nhà:</strong> Loa thông minh (Google Home, Alexa) nghe lệnh giọng nói và bật đèn, mở nhạc.</li><li>☕ <strong>Tại quán cafe:</strong> Camera nhận diện khách quen, hệ thống tự gợi ý món họ hay gọi.</li><li>🏫 <strong>Tại trường:</strong> Phần mềm chấm bài tự luận ngắn, phát hiện bài viết đạo văn.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="ai-la-gi" tabindex="-1">AI là gì? <a class="header-anchor" href="#ai-la-gi" aria-label="Permalink to &quot;AI là gì?&quot;">​</a></h3><p><strong>Trí tuệ nhân tạo (Artificial Intelligence – AI)</strong> là lĩnh vực khoa học máy tính nghiên cứu cách tạo ra các chương trình máy tính có khả năng thực hiện những nhiệm vụ thường đòi hỏi trí tuệ của con người.</p><p>Những khả năng đó bao gồm:</p><ul><li><strong>Hiểu ngôn ngữ</strong> (đọc, viết, nói chuyện)</li><li><strong>Nhận diện hình ảnh</strong> (khuôn mặt, đồ vật)</li><li><strong>Ra quyết định</strong> (chọn phim gợi ý, chẩn đoán bệnh)</li><li><strong>Học từ dữ liệu</strong> (càng dùng nhiều, càng thông minh hơn)</li></ul><h3 id="nlp-–-xu-ly-ngon-ngu-tu-nhien-la-gi" tabindex="-1">NLP – Xử lý ngôn ngữ tự nhiên là gì? <a class="header-anchor" href="#nlp-–-xu-ly-ngon-ngu-tu-nhien-la-gi" aria-label="Permalink to &quot;NLP – Xử lý ngôn ngữ tự nhiên là gì?&quot;">​</a></h3><p><strong>NLP (Natural Language Processing – Xử lý ngôn ngữ tự nhiên)</strong> là nhánh của AI giúp máy tính hiểu, phân tích và tạo ra ngôn ngữ của con người (tiếng Việt, tiếng Anh, v.v.).</p><p>Các thành phần chính của NLP:</p><table tabindex="0"><thead><tr><th>Thành phần</th><th>Ý nghĩa</th><th>Ví dụ</th></tr></thead><tbody><tr><td>Tokenization</td><td>Tách câu thành từng từ</td><td>&quot;Tôi học AI&quot; → [&quot;Tôi&quot;, &quot;học&quot;, &quot;AI&quot;]</td></tr><tr><td>Phân tích cú pháp</td><td>Hiểu cấu trúc câu</td><td>Xác định chủ ngữ, vị ngữ</td></tr><tr><td>Phân tích cảm xúc</td><td>Nhận biết cảm xúc trong văn bản</td><td>&quot;Sản phẩm tệ quá&quot; → Tiêu cực</td></tr><tr><td>Dịch máy</td><td>Dịch từ ngôn ngữ này sang ngôn ngữ khác</td><td>Google Dịch</td></tr></tbody></table><h3 id="nhan-dien-khuon-mat-la-gi" tabindex="-1">Nhận diện khuôn mặt là gì? <a class="header-anchor" href="#nhan-dien-khuon-mat-la-gi" aria-label="Permalink to &quot;Nhận diện khuôn mặt là gì?&quot;">​</a></h3><p><strong>Nhận diện khuôn mặt (Face Recognition)</strong> là công nghệ AI phân tích hình ảnh khuôn mặt và so sánh với cơ sở dữ liệu để xác định danh tính.</p><h3 id="he-goi-y-recommendation-system-la-gi" tabindex="-1">Hệ gợi ý (Recommendation System) là gì? <a class="header-anchor" href="#he-goi-y-recommendation-system-la-gi" aria-label="Permalink to &quot;Hệ gợi ý (Recommendation System) là gì?&quot;">​</a></h3><p><strong>Hệ gợi ý</strong> là hệ thống AI phân tích hành vi người dùng (xem gì, thích gì, mua gì) và đề xuất nội dung/sản phẩm phù hợp.</p><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="thuc-chat-ai-la-gi" tabindex="-1">Thực chất AI là gì? <a class="header-anchor" href="#thuc-chat-ai-la-gi" aria-label="Permalink to &quot;Thực chất AI là gì?&quot;">​</a></h3><p>Hãy tưởng tượng bạn dạy một đứa trẻ nhận biết con chó bằng cách cho nó xem 1.000 bức ảnh con chó và 1.000 bức ảnh không phải chó. Sau khi xem đủ nhiều, đứa trẻ đó sẽ nhận ra con chó dù chưa thấy bức ảnh đó bao giờ.</p><p><strong>AI hoạt động y như vậy</strong> — nhưng thay vì đứa trẻ, đó là một chương trình máy tính; thay vì mắt và não, đó là các thuật toán và con số.</p><h3 id="nlp-–-ngon-ngu-voi-may-tinh" tabindex="-1">NLP – Ngôn ngữ với máy tính <a class="header-anchor" href="#nlp-–-ngon-ngu-voi-may-tinh" aria-label="Permalink to &quot;NLP – Ngôn ngữ với máy tính&quot;">​</a></h3><p>Máy tính vốn chỉ hiểu số (0 và 1). NLP là &quot;phiên dịch viên&quot; biến ngôn ngữ của con người thành dạng số mà máy có thể xử lý, rồi biến kết quả số đó trở lại thành ngôn ngữ người đọc được.</p><h3 id="nhan-dien-khuon-mat-–-nhu-tham-tu-so" tabindex="-1">Nhận diện khuôn mặt – như thám tử số <a class="header-anchor" href="#nhan-dien-khuon-mat-–-nhu-tham-tu-so" aria-label="Permalink to &quot;Nhận diện khuôn mặt – như thám tử số&quot;">​</a></h3><p>Mỗi khuôn mặt có những đặc điểm riêng: khoảng cách giữa hai mắt, hình dạng mũi, độ rộng của miệng. AI đo các điểm đặc trưng này, biến thành một &quot;dấu vân tay khuôn mặt&quot; (face embedding), rồi so sánh với dữ liệu đã lưu.</p><h3 id="he-goi-y-–-nhu-nguoi-ban-hieu-ban-nhat" tabindex="-1">Hệ gợi ý – như người bạn hiểu bạn nhất <a class="header-anchor" href="#he-goi-y-–-nhu-nguoi-ban-hieu-ban-nhat" aria-label="Permalink to &quot;Hệ gợi ý – như người bạn hiểu bạn nhất&quot;">​</a></h3><p>Khi bạn xem video cắt tóc ngắn trên TikTok, thuật toán ghi lại điều đó. Khi bạn dừng lại 10 giây ở video mèo, nó cũng ghi lại. Dần dần nó vẽ ra &quot;chân dung số&quot; của bạn và đối chiếu với hàng triệu người dùng khác có sở thích giống bạn để gợi ý nội dung.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="chatbot-hoat-đong-nhu-the-nao" tabindex="-1">Chatbot hoạt động như thế nào? <a class="header-anchor" href="#chatbot-hoat-đong-nhu-the-nao" aria-label="Permalink to &quot;Chatbot hoạt động như thế nào?&quot;">​</a></h3><ol><li><strong>Người dùng nhập câu hỏi:</strong> &quot;Thời tiết hôm nay thế nào?&quot;</li><li><strong>NLP phân tích câu:</strong> Xác định đây là câu hỏi về thời tiết, địa điểm chưa rõ.</li><li><strong>Hệ thống tra cứu ngữ cảnh:</strong> Lấy vị trí của người dùng (nếu được phép).</li><li><strong>Truy vấn dữ liệu:</strong> Gọi API thời tiết để lấy thông tin.</li><li><strong>Sinh câu trả lời:</strong> Tạo câu văn tự nhiên từ dữ liệu thô.</li><li><strong>Trả lời người dùng:</strong> &quot;Hôm nay tại Hà Nội trời nhiều mây, 28°C.&quot;</li></ol><h3 id="tiktok-goi-y-video-nhu-the-nao" tabindex="-1">TikTok gợi ý video như thế nào? <a class="header-anchor" href="#tiktok-goi-y-video-nhu-the-nao" aria-label="Permalink to &quot;TikTok gợi ý video như thế nào?&quot;">​</a></h3><ol><li><strong>Thu thập dữ liệu:</strong> Bạn xem video nào, bao lâu, có thích/chia sẻ không.</li><li><strong>Xây dựng hồ sơ người dùng:</strong> Thuật toán tạo &quot;vector sở thích&quot; của bạn.</li><li><strong>So sánh với người dùng khác:</strong> Tìm những người có sở thích tương tự.</li><li><strong>Lọc nội dung phù hợp:</strong> Chọn video mà người giống bạn đã thích.</li><li><strong>Xếp hạng và hiển thị:</strong> Sắp xếp video theo độ phù hợp dự đoán.</li><li><strong>Cập nhật liên tục:</strong> Phản hồi của bạn (xem tiếp hay bỏ qua) cập nhật lại mô hình.</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-bo-loc-thu-rac-spam-filter" tabindex="-1">Ví dụ 1 – Cơ bản: Bộ lọc thư rác (Spam Filter) <a class="header-anchor" href="#vi-du-1-–-co-ban-bo-loc-thu-rac-spam-filter" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Bộ lọc thư rác (Spam Filter)&quot;">​</a></h3><p>Email &quot;Bạn đã trúng 1 tỷ đồng! Click ngay!&quot; bị AI nhận ra là spam vì:</p><ul><li>Có từ khóa đáng ngờ: &quot;trúng thưởng&quot;, &quot;click ngay&quot;</li><li>Cấu trúc câu giống 10.000 email spam trước đó</li><li>Người gửi không có trong danh sách liên hệ</li></ul><p>→ AI học từ hàng triệu email spam để nhận diện cái mới.</p><h3 id="vi-du-2-–-đoi-thuc-youtube-goi-y-noi-dung" tabindex="-1">Ví dụ 2 – Đời thực: YouTube gợi ý nội dung <a class="header-anchor" href="#vi-du-2-–-đoi-thuc-youtube-goi-y-noi-dung" aria-label="Permalink to &quot;Ví dụ 2 – Đời thực: YouTube gợi ý nội dung&quot;">​</a></h3><p>Một học sinh hay xem video toán học và nhạc K-pop. YouTube nhận ra pattern này, rồi gợi ý: video giải toán bằng nhạc, video học tiếng Hàn, hay video toán nâng cao. Điều này xảy ra vì AI tìm được nhóm người dùng khác cũng có hai sở thích tương tự.</p><h3 id="vi-du-3-–-nang-cao-he-thong-chan-đoan-benh-qua-anh-x-quang" tabindex="-1">Ví dụ 3 – Nâng cao: Hệ thống chẩn đoán bệnh qua ảnh X-quang <a class="header-anchor" href="#vi-du-3-–-nang-cao-he-thong-chan-đoan-benh-qua-anh-x-quang" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Hệ thống chẩn đoán bệnh qua ảnh X-quang&quot;">​</a></h3><p>Bác sĩ AI được huấn luyện trên 500.000 ảnh X-quang có nhãn (ung thư / không ung thư). Khi nhận ảnh X-quang mới, AI chiết xuất đặc trưng từ ảnh (hình dạng bất thường, mật độ mô), so sánh với dữ liệu học, rồi đưa ra xác suất: &quot;85% khả năng có khối u ở thùy trên phổi phải.&quot; Bác sĩ vẫn ra quyết định cuối, nhưng AI hỗ trợ tốc độ và độ chính xác.</p><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-cac-ung-dung-ai" tabindex="-1">So sánh các ứng dụng AI <a class="header-anchor" href="#so-sanh-cac-ung-dung-ai" aria-label="Permalink to &quot;So sánh các ứng dụng AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ứng dụng</th><th>Công nghệ AI dùng</th><th>Dữ liệu đầu vào</th><th>Đầu ra</th></tr></thead><tbody><tr><td>Chatbot (ChatGPT)</td><td>NLP, mô hình ngôn ngữ lớn</td><td>Văn bản</td><td>Văn bản trả lời</td></tr><tr><td>Mở khóa khuôn mặt</td><td>Nhận diện khuôn mặt</td><td>Hình ảnh camera</td><td>Xác nhận / Từ chối</td></tr><tr><td>TikTok / YouTube</td><td>Hệ gợi ý</td><td>Lịch sử xem, tương tác</td><td>Danh sách video</td></tr><tr><td>Google Dịch</td><td>NLP, dịch máy</td><td>Văn bản ngôn ngữ A</td><td>Văn bản ngôn ngữ B</td></tr><tr><td>Lọc thư rác</td><td>Phân loại văn bản</td><td>Nội dung email</td><td>Spam / Không spam</td></tr></tbody></table><h3 id="so-sanh-ai-yeu-vs-ai-manh" tabindex="-1">So sánh AI yếu vs AI mạnh <a class="header-anchor" href="#so-sanh-ai-yeu-vs-ai-manh" aria-label="Permalink to &quot;So sánh AI yếu vs AI mạnh&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>AI yếu (Narrow AI)</th><th>AI mạnh (General AI)</th></tr></thead><tbody><tr><td>Phạm vi</td><td>Chỉ làm 1 việc</td><td>Làm nhiều việc như người</td></tr><tr><td>Ví dụ</td><td>AlphaGo, Siri, lọc spam</td><td>Chưa tồn tại trong thực tế</td></tr><tr><td>Trạng thái hiện tại</td><td>Đang dùng phổ biến</td><td>Còn là lý thuyết</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li><strong>AI</strong> = chương trình máy tính thực hiện nhiệm vụ đòi hỏi trí tuệ người</li><li><strong>NLP</strong> = giúp máy hiểu và tạo ngôn ngữ tự nhiên (tiếng nói, văn bản)</li><li><strong>Nhận diện khuôn mặt</strong> = đo đặc điểm khuôn mặt → so sánh → xác định danh tính</li><li><strong>Hệ gợi ý</strong> = phân tích hành vi người dùng → đề xuất nội dung phù hợp</li><li><strong>Chatbot</strong> dùng NLP để hiểu câu hỏi và sinh câu trả lời</li><li><strong>TikTok/YouTube</strong> dùng hệ gợi ý dựa trên lịch sử xem và tương tác</li><li>AI hiện nay đều là <strong>AI yếu</strong> (chỉ giỏi 1 lĩnh vực cụ thể)</li><li>AI học từ <strong>dữ liệu</strong> — càng nhiều dữ liệu, càng chính xác</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><p><strong>Câu 1 (Dễ):</strong> NLP là viết tắt của cụm từ tiếng Anh nào? Cho một ví dụ ứng dụng NLP trong đời sống.</p><blockquote><p><strong>Đáp án:</strong> NLP = Natural Language Processing (Xử lý ngôn ngữ tự nhiên). Ví dụ: Google Dịch, trợ lý giọng nói Siri, chatbot hỗ trợ khách hàng.</p></blockquote><hr><p><strong>Câu 2 (Dễ):</strong> Hệ gợi ý của Netflix dựa vào những dữ liệu nào để đề xuất phim cho bạn?</p><blockquote><p><strong>Đáp án:</strong> Netflix phân tích: lịch sử phim đã xem, thể loại yêu thích, thời gian xem (xem hết hay bỏ nửa chừng), đánh giá sao, và so sánh với những người dùng có sở thích tương tự.</p></blockquote><hr><p><strong>Câu 3 (Trung bình):</strong> Mô tả 3 bước cơ bản trong quá trình nhận diện khuôn mặt để mở khóa điện thoại.</p><blockquote><p><strong>Đáp án:</strong></p><ol><li><strong>Thu thập:</strong> Camera chụp ảnh khuôn mặt người dùng.</li><li><strong>Chiết xuất đặc trưng:</strong> AI đo các điểm đặc trưng (khoảng cách mắt, hình dạng mũi…) tạo thành &quot;dấu vân tay khuôn mặt&quot;.</li><li><strong>So sánh:</strong> Đối chiếu với dữ liệu khuôn mặt đã đăng ký. Nếu độ tương đồng vượt ngưỡng → mở khóa.</li></ol></blockquote><hr><p><strong>Câu 4 (Trung bình):</strong> Tại sao AI càng được dùng nhiều thì càng hoạt động tốt hơn? Giải thích ngắn gọn.</p><blockquote><p><strong>Đáp án:</strong> AI học từ dữ liệu. Càng nhiều người dùng, AI thu thập được càng nhiều dữ liệu về hành vi, sở thích, và các trường hợp đặc biệt. Dữ liệu nhiều hơn giúp mô hình AI được huấn luyện lại với độ chính xác cao hơn và bao quát được nhiều tình huống hơn.</p></blockquote><hr><p><strong>Câu 5 (Ứng dụng):</strong> Một cửa hàng sách muốn xây dựng hệ gợi ý sách cho khách hàng. Hãy mô tả dữ liệu cần thu thập và cách hệ thống hoạt động.</p><blockquote><p><strong>Đáp án gợi ý:</strong></p><ul><li><strong>Dữ liệu cần thu thập:</strong> sách đã mua, sách đã xem nhưng chưa mua, thể loại yêu thích, đánh giá của khách, thời gian duyệt trang.</li><li><strong>Cách hoạt động:</strong><ol><li>Xây dựng hồ sơ sở thích của từng khách.</li><li>Nhóm khách hàng có sở thích tương tự lại.</li><li>Khi khách A (thích trinh thám) ghé thăm, gợi ý sách mà các khách cùng nhóm đã mua.</li><li>Cập nhật liên tục theo phản hồi thực tế.</li></ol></li></ul></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lỗi thường gặp</th><th>Cách hiểu đúng</th></tr></thead><tbody><tr><td>Nghĩ AI &quot;hiểu&quot; như con người</td><td>AI không hiểu nghĩa — nó nhận dạng mẫu trong dữ liệu. Chatbot không &quot;biết&quot; bạn buồn, nó chỉ nhận ra từ ngữ liên quan đến cảm xúc buồn.</td></tr><tr><td>Nhầm NLP chỉ là dịch thuật</td><td>NLP bao gồm nhiều thứ hơn: phân tích cảm xúc, tóm tắt văn bản, nhận dạng giọng nói, chatbot, v.v.</td></tr><tr><td>Cho rằng hệ gợi ý &quot;đọc được suy nghĩ&quot;</td><td>Hệ gợi ý chỉ dựa trên hành vi đã ghi lại, không thực sự biết bạn muốn gì — nó đoán dựa trên thói quen.</td></tr><tr><td>Nghĩ nhận diện khuôn mặt là 100% chính xác</td><td>Nhận diện khuôn mặt có thể sai, đặc biệt khi ánh sáng yếu, góc chụp lạ, hoặc hai người có ngoại hình giống nhau.</td></tr><tr><td>Nhầm AI yếu và AI mạnh</td><td>AI hiện tại đều là AI yếu — giỏi một việc cụ thể. AI mạnh (có thể làm mọi thứ như người) chưa tồn tại.</td></tr></tbody></table>',76)])])}const m=t(o,[["render",g]]);export{s as __pageData,m as default};
